  "shader_code": "/*
  Mechanical Gear with Fixed Teeth Overlap
  Fixed: Teeth geometry now extends into the gear body to ensure a solid, continuous shape without gaps.
*/

#ifndef PI
#define PI 3.14159265359
#endif

// Helper: 2D Rotation
float2 Rotate2D(float2 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return float2(c * p.x - s * p.y, s * p.x + c * p.y);
}

// Helper: Box SDF
float sdBox(float2 p, float2 b) {
    float2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

void GearShape_float(float2 UV, float TeethCount, float Size, float ToothDepth, float HoleRadius, float Rotation, float4 BodyColor, float4 HoleColor, out float4 outColor) {
    float2 p = UV - 0.5;

    // 1) Apply global rotation
    p = Rotate2D(p, -Rotation);

    // 2) Parameters
    float N = max(3.0, round(TeethCount));
    float rOuter = Size;
    // The inner body radius is the outer size minus the tooth depth
    float rInner = max(0.001, Size - ToothDepth);

    // 3) Angular Domain Repetition
    // We determine which angular sector the pixel belongs to
    float angle = atan2(p.y, p.x);
    float angleStep = 2.0 * PI / N;

    // Round to the nearest sector index to center the domain around the tooth
    float sector = floor(angle / angleStep + 0.5);
    float sectorAngle = sector * angleStep;

    // Rotate 'p' so the current sector aligns with the X-axis
    float2 pLocal = Rotate2D(p, -sectorAngle);

    // 4) Shape Definition

    // TOOTH (Box SDF)
    // FIX: To prevent gaps, we extend the tooth box *inwards* past rInner.
    // We add an overlap factor proportional to the depth.
    float overlap = ToothDepth * 0.2 + 0.01;

    // The box spans from [rInner - overlap] to [rOuter] along the X-axis
    float toothInnerX = rInner - overlap;
    float toothOuterX = rOuter;

    float boxCenterX = (toothInnerX + toothOuterX) * 0.5;
    float boxHalfWidthX = (toothOuterX - toothInnerX) * 0.5;

    // The tooth width (Y-axis) is derived from the arc length at rInner (approx 50% duty cycle)
    float boxHalfWidthY = (rInner * angleStep) * 0.25;

    float dTooth = sdBox(pLocal - float2(boxCenterX, 0.0), float2(boxHalfWidthX, boxHalfWidthY));

    // BODY (Circle SDF)
    float dBody = length(p) - rInner;

    // GEAR SHAPE (Union of Body and Tooth)
    // Using min() creates a solid union. Because the tooth overlaps the body, the transition is seamless.
    float dGear = min(dBody, dTooth);

    // HOLE (Circle SDF)
    float dHole = length(p) - HoleRadius;

    // 5) Anti-aliasing and Masking
    // fwidth allows for consistent anti-aliasing regardless of zoom/resolution
    float aa = fwidth(length(p));
    aa = max(aa, 0.0005); 

    float gearMask = smoothstep(aa, -aa, dGear);
    float holeMask = smoothstep(aa, -aa, dHole);

    // 6) Composition
    // The body is visible where the gear is solid AND the hole is not.
    float bodyAlpha = saturate(gearMask - holeMask);

    // The hole color is visible exactly where the hole mask is 1.
    float holeAlpha = holeMask;

    // Combine colors
    // Assuming standard alpha blending logic
    outColor = BodyColor * bodyAlpha + HoleColor * holeAlpha;
}",
